      download: "Pobierz",
      title: "Zgodność z modami",
      lead: "Które mody działają z MOP - REVIVAL i co dla nich robi. Większość modów nie potrzebuje niczego.",
      searchLabel: "Szukaj modów",
      search: "Szukaj wśród {n} modów po nazwie lub ID",
